"""The tester's one table: each session's target, run status and stored report."""

from datetime import datetime
from enum import StrEnum
from typing import Any

from sqlalchemy import DateTime, Enum, Text
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import Mapped, mapped_column

from tester.db import Base


class RunStatus(StrEnum):
    READY = "ready"
    RUNNING = "running"
    FINISHED = "finished"
    ABORTED = "aborted"


class StoredSession(Base):
    __tablename__ = "tester_sessions"

    # Generated by the tester and sent to the target's /test/setup.
    session_id: Mapped[str] = mapped_column(Text, primary_key=True)
    # The system base URL under test.
    target_url: Mapped[str] = mapped_column(Text, nullable=False)
    # Stored by value ("ready"), like the app's enums.
    status: Mapped[RunStatus] = mapped_column(
        Enum(
            RunStatus,
            name="tester_run_status",
            values_callable=lambda members: [m.value for m in members],
            validate_strings=True,
        ),
        nullable=False,
    )
    # The SuiteReport; SQL NULL until the run finishes or aborts.
    report: Mapped[dict[str, Any] | None] = mapped_column(JSONB(none_as_null=True))
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    finished_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
